package com.college.hospitalmanagement;import java.util.*;import org.springframework.data.jpa.repository.*;import jakarta.persistence.LockModeType;public interface BedRepository extends JpaRepository<Bed,Long>{Optional<Bed> findByRoomIdAndBedNumber(Long roomId,String bedNumber);List<Bed> findByRoomId(Long roomId);List<Bed> findByWardId(Long wardId);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select b from Bed b where b.id=:id") Optional<Bed> findLockedById(Long id);}
